    async loadActiveActionRunEvents(): Promise<ActionRunEvent[]> {
        return this.request<ActionRunEvent[]>('loadActiveActionRunEvents', [])
    }

    async getCodexRateLimits(): Promise<CodexRateLimitSnapshot | null> {
